import React from "react";

export default function About() {
  return (
    <div className="about-page">

      <h1 className="main-title">
        About <span>Me</span>
      </h1>

      <div className="about-container">

        {/* INTRO */}
        <div className="about-intro">
          <p>
            I am an enthusiastic and dedicated Information Technology student 
            passionate about building modern digital solutions that are both 
            functional and user-friendly.
          </p>

          <p>
            I enjoy transforming ideas into real-world applications by combining 
            creativity with technical knowledge. I continuously explore new 
            technologies and enhance my problem-solving skills through hands-on projects.
          </p>
        </div>

        {/* GRID CARDS */}
        <div className="about-grid">

          {/* WHAT I DO */}
          <div className="card large">
            <h3>🚀 What I Do</h3>
            <p>
              I develop responsive web applications, design intuitive user 
              interfaces, and build innovative systems that solve real-world problems. 
              My focus is on creating scalable and meaningful digital experiences.
            </p>
          </div>

          {/* EDUCATION */}
          <div className="card">
            <div className="card-header">
              <h3>🎓 Education</h3>
              <span className="year">2023–2027</span>
            </div>
            <p><strong>B.Tech – Information Technology</strong></p>
            <p className="college">Panimalar Engineering College</p>
            <p>
              Building strong foundations in software development, database 
              systems, and modern technologies through academic and project work.
            </p>
          </div>

          {/* INTERESTS */}
          <div className="card">
            <h3>💡 Interests</h3>
            <ul>
              <li>Full Stack Development</li>
              <li>Data Analytics</li>
              <li>UI/UX Design</li>
              <li>Smart System Development</li>
            </ul>
          </div>

        </div>

        {/* STATS */}
        <div className="stats">
          <div className="stat-box">
            <h3>5+</h3>
            <p>Projects</p>
          </div>
          <div className="stat-box">
            <h3>10+</h3>
            <p>Technologies</p>
          </div>
          <div className="stat-box">
            <h3>2+</h3>
            <p>Domains</p>
          </div>
        </div>

      </div>

      <style>{`

        .about-page {
          min-height: 100vh;
          padding: 60px 12%;
          font-family: "Poppins", sans-serif;
          background: linear-gradient(135deg, #0f172a, #020617);
          color: white;
        }

        .main-title {
          text-align: center;
          font-size: 44px;
          margin-bottom: 30px;
        }

        .main-title span {
          color: #38BDF8;
        }

        .about-container {
          max-width: 1100px;
          margin: auto;
        }

        /* INTRO */
        .about-intro {
          text-align: center;
          max-width: 750px;
          margin: 0 auto 40px;
        }

        .about-intro p {
          color: #cbd5e1;
          line-height: 1.8;
          margin-bottom: 10px;
        }

        /* GRID */
        .about-grid {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 25px;
        }

        .card {
          background: rgba(255,255,255,0.05);
          padding: 22px;
          border-radius: 14px;
          border: 1px solid rgba(56,189,248,0.2);
          transition: 0.3s;
        }

        .card.large {
          grid-column: span 2;
        }

        .card:hover {
          transform: translateY(-5px);
          box-shadow: 0 0 25px rgba(56,189,248,0.4);
        }

        .card h3 {
          margin-bottom: 10px;
          color: #38BDF8;
        }

        .card p, li {
          color: #cbd5e1;
          font-size: 15px;
        }

        /* HEADER */
        .card-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 8px;
        }

        /* FIXED YEAR BOX */
        .year {
          background: rgba(56,189,248,0.2);
          color: #38BDF8;
          padding: 2px 10px;
          border-radius: 12px;
          font-size: 11px;
          font-weight: 600;
        }

        .college {
          color: #7dd3fc;
          font-weight: 500;
        }

        ul {
          padding-left: 18px;
        }

        /* STATS */
        .stats {
          display: flex;
          justify-content: space-between;
          margin-top: 40px;
          gap: 20px;
        }

        .stat-box {
          flex: 1;
          text-align: center;
          padding: 18px;
          border-radius: 12px;
          background: rgba(255,255,255,0.05);
          border: 1px solid rgba(56,189,248,0.2);
        }

        .stat-box h3 {
          color: #38BDF8;
        }

        /* RESPONSIVE */
        @media (max-width: 768px) {
          .about-grid {
            grid-template-columns: 1fr;
          }

          .card.large {
            grid-column: span 1;
          }

          .stats {
            flex-direction: column;
          }
        }

      `}</style>

    </div>
  );
}
